function useRoute() {
  const [path, setPath] = useState(window.location.pathname || "/dashboard");
  useEffect(() => {
    const onPop = () => setPath(window.location.pathname || "/dashboard");
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);
  const go = (next: string) => {
    window.history.pushState({}, "", next);
    setPath(next);
  };
  return { path, go };
}

function useFetch<T>(path: string) {
  const [state, setState] = useState<{ data?: T; error?: string; loading: boolean }>({ loading: true });
  const reload = () => {
    setState({ loading: true });
    api<T>(path).then((data) => setState({ data, loading: false })).catch((error: Error) => setState({ error: error.message, loading: false }));
  };
  useEffect(reload, [path]);
  return { ...state, reload };
}

function toneForStatus(value: string): Tone {
  const status = value.toUpperCase();
  if (["CRITICAL", "BLOCKED", "HASH_MISMATCH", "AT_RISK", "NO_ELIGIBLE_ROUTE"].some((v) => status.includes(v))) return "critical";
  if (["HIGH", "MEDIUM", "ON_HOLD", "STALE", "EXPIRING", "WATCH", "PENDING", "REVIEW", "AWAITING", "PARTIALLY"].some((v) => status.includes(v))) return "warning";
  if (["CLEAR", "VERIFIED", "POSTED", "READY", "SETTLED", "ON_TRACK", "APPROVED"].some((v) => status.includes(v))) return "positive";
  return "neutral";
}

function Badge({ children, tone = "neutral" }: { children: React.ReactNode; tone?: Tone }) {
  return <span className={`badge badge-${tone}`}><span className="badge-dot" />{children}</span>;
}

function Provenance({ mode = "DEMO_SYNTHETIC" }: { mode?: string }) {
  const demo = mode !== "MANAGED_DATABASE";
  return <span className={`provenance ${demo ? "provenance-demo" : "provenance-live"}`}><span className="provenance-dot" />{demo ? "Synthetic demonstration data" : "Managed database"}</span>;
}

function PageTitle({ eyebrow, title, description, actions }: { eyebrow: string; title: string; description: string; actions?: React.ReactNode }) {
  return <div className="page-title"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{actions && <div className="title-actions">{actions}</div>}</div>;
}

function LoadingBlock() { return <div className="loading-block"><div className="skeleton skeleton-wide" /><div className="skeleton skeleton-short" /><div className="skeleton skeleton-row" /></div>; }
function ErrorBlock({ message, retry }: { message: string; retry: () => void }) { return <div className="state-block state-error"><AlertTriangle size={18} /><div><strong>Unable to load this view</strong><p>{message}</p><button className="button button-secondary" onClick={retry}>Retry</button></div></div>; }
function EmptyBlock({ title = "No records in this view", text = "Records will appear when the relevant workflow produces evidence." }: { title?: string; text?: string }) { return <div className="state-block"><FileWarning size={18} /><div><strong>{title}</strong><p>{text}</p></div></div>; }

function Kpi({ label, value, sub, icon: Icon, tone = "neutral" }: { label: string; value: string; sub: string; icon: typeof Activity; tone?: Tone }) {
  return <div className="kpi-card"><div className="kpi-top"><span className="kpi-label">{label}</span><span className={`kpi-icon kpi-${tone}`}><Icon size={16} /></span></div><div className="kpi-value">{value}</div><div className="kpi-sub">{sub}</div></div>;
}

function DataTable({ columns, rows, onRowClick }: { columns: { key: string; label: string; render?: (value: unknown, row: Row) => React.ReactNode }[]; rows: Row[]; onRowClick?: (row: Row) => void }) {
  if (!rows.length) return <EmptyBlock />;
  return <div className="table-wrap"><table><thead><tr>{columns.map((column) => <th key={column.key}>{column.label}</th>)}</tr></thead><tbody>{rows.map((row, index) => <tr key={String(row.id ?? row.tradeReference ?? index)} onClick={() => onRowClick?.(row)} className={onRowClick ? "clickable-row" : ""}>{columns.map((column) => <td key={column.key}>{column.render ? column.render(row[column.key], row) : String(row[column.key] ?? "—")}</td>)}</tr>)}</tbody></table></div>;
}

